-- This migration prepares the database for proper auth sync
-- The demo users in public.users will be updated when auth users are created

-- First, let's make sure the trigger handles updates properly
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
DROP FUNCTION IF EXISTS public.handle_new_user();

-- Create improved function that handles both new users and existing email conflicts
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
DECLARE
  existing_user_id UUID;
BEGIN
  -- Check if a user with this email already exists in public.users
  SELECT user_id INTO existing_user_id
  FROM public.users
  WHERE email = NEW.email;

  IF existing_user_id IS NOT NULL THEN
    -- Update existing user with the new auth user_id
    UPDATE public.users
    SET 
      user_id = NEW.id,
      first_name = COALESCE(NEW.raw_user_meta_data->>'first_name', first_name),
      last_name = COALESCE(NEW.raw_user_meta_data->>'last_name', last_name),
      phone = COALESCE(NEW.raw_user_meta_data->>'phone', phone),
      role = COALESCE(NEW.raw_user_meta_data->>'role', role)
    WHERE email = NEW.email;

    -- Update all related records to use the new user_id
    UPDATE public.children SET parent_id = NEW.id WHERE parent_id = existing_user_id;
    UPDATE public.attendance SET marked_by = NEW.id WHERE marked_by = existing_user_id;
    UPDATE public.events SET created_by_id = NEW.id WHERE created_by_id = existing_user_id;
    UPDATE public.event_notifications SET parent_id = NEW.id WHERE parent_id = existing_user_id;
    UPDATE public.payments SET parent_id = NEW.id WHERE parent_id = existing_user_id;
    UPDATE public.announcements SET created_by_id = NEW.id WHERE created_by_id = existing_user_id;
    UPDATE public.media SET uploaded_by = NEW.id WHERE uploaded_by = existing_user_id;
  ELSE
    -- Insert new user
    INSERT INTO public.users (user_id, first_name, last_name, email, phone, role, is_active)
    VALUES (
      NEW.id,
      COALESCE(NEW.raw_user_meta_data->>'first_name', 'User'),
      COALESCE(NEW.raw_user_meta_data->>'last_name', 'Name'),
      NEW.email,
      COALESCE(NEW.raw_user_meta_data->>'phone', NULL),
      COALESCE(NEW.raw_user_meta_data->>'role', 'parent'),
      true
    );
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Recreate trigger
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- Add comment explaining the setup process
COMMENT ON FUNCTION public.handle_new_user() IS 
  'Syncs auth.users with public.users. When a new auth user is created, this function either creates a new public.users record or updates an existing one with matching email, ensuring all foreign key relationships are maintained.';

